function watchDetail(r){return `<section class="panel rail-detail"><div class="panel-head"><h2><span class="dot ${r.flags.length?'warn':'ok'}"></span>${esc(r.n)}${starBtn(r)}</h2><button class="ghost small" id="watch-close" aria-label="关闭详情">✕</button></div><div class="panel-body"><div class="detail-stats"><div><span>已回访</span><strong>${r.d}<em>/${r.t}</em></strong></div><div><span>到点未回访</span><strong class="${r.due.length?'warn-text':''}">${r.due.length}</strong></div><div><span>最近操作</span><strong class="${r.idle>=IDLE_MIN?'warn-text':''}">${r.last?since(r.idle):'无'}</strong></div></div>${r.flags.length?`<div class="flags">${r.flags.map(f=>`<span class="flag">${f}</span>`).join('')}</div>`:''}<div class="row"><button class="primary small" data-nudge="${esc(r.n)}">提醒${esc(r.n)}</button><button class="small" data-employee-detail="${esc(r.n)}">全部名单</button></div>${r.due.length?`<h3>到点未回访</h3><ul class="due-list">${r.due.map(c=>`<li><span>${esc(c.name)}</span><span class="warn-text num">约 ${hm(c.next)}</span></li>`).join('')}</ul>`:''}<h3>今天的操作 · ${r.own.length} 条</h3>${r.own.length?`<ol class="feed">${r.own.map(e=>`<li class="${e.kind||''}"><span class="num">${hm(e.t)}</span><span>${esc(e.text)}</span></li>`).join('')}</ol>`:'<p class="sub">今天还没有操作记录。员工在工作台点「完成」后这里才会出现。</p>'}</div></section>`}
function watchRail(ev){const help=state.help.filter(h=>h.status==='待处理').sort((a,b)=>new Date(a.at)-new Date(b.at)),now=Date.now();
return `<section class="panel rail-todo"><div class="panel-head"><h2>待我处理 <span class="count">${help.length+(state.payments.filter(p=>!p.verified).length?1:0)}</span></h2><button class="ghost small" data-page="coaching">全部求助</button></div><div class="panel-body">${help.map(h=>`<div class="todo-item"><div class="row between"><strong>${esc(h.who)} · ${esc(h.customer)}</strong><span class="rail-meta warn">等了 ${ago(Math.max(0,Math.floor((now-new Date(h.at))/60000)))}</span></div><p class="clamp">${esc(h.text)}</p><button class="small" data-handle="${h.id}">回复</button></div>`).join('')}${state.payments.filter(p=>!p.verified).length?`<div class="todo-item"><div class="row between"><strong>充值待核实</strong><span class="rail-meta">${state.payments.filter(p=>!p.verified).length} 笔</span></div><button class="small" data-page="reports">去核实</button></div>`:''}${help.length||state.payments.filter(p=>!p.verified).length?'':'<p class="sub">暂无待处理事项</p>'}</div></section><section class="panel rail-feed"><div class="panel-head"><h2>实时动态</h2><span class="proto-note">今天 ${ev.length} 条</span></div><ol class="feed watch-feed">${ev.slice(0,80).map(e=>`<li class="${e.kind||''}"><span class="num">${hm(e.t)}</span><span>${e.kind==='nudge'?'你':`<button class="link-button" data-watch-pick="${esc(e.who)}">${esc(e.who)}</button>`} ${esc(e.text)}</span></li>`).join('')||'<li class="sub">今天还没有动态</li>'}</ol></section>`}
function directorOverview(){const ev=teamEvents(),rows=staffRows(ev),T=rows.reduce((a,r)=>a+r.t,0),D=rows.reduce((a,r)=>a+r.d,0),due=rows.reduce((a,r)=>a+r.due.length,0),bad=rows.filter(r=>r.warn),todo=state.help.filter(h=>h.status==='待处理').length+(state.payments.filter(p=>!p.verified).length?1:0),yd=D-yesterdayNow(T),sel=rows.find(r=>r.n===watchSel),list=watchFilter==='warn'?bad:rows;
return `<div class="watch"><div class="watch-top"><div class="watch-title"><h1>团队总览</h1><span class="live"><i></i>${hm(Date.now())} 更新 · 每 30 秒刷新</span></div><div class="kpis">${kpi('已回访',`${D}<em>/${T}</em>`,`<span class="progress"><i style="width:${T?D/T*100:0}%"></i></span>${T?Math.round(D/T*100):0}%`)}${kpi('比昨天同一时刻',yd===0?'持平':`${yd>0?'+':'−'}${Math.abs(yd)}`,'昨天为示例数据',yd<0?'warn':'')}${kpi('需要关注的员工',`${bad.length}<em>/${rows.length}</em>`,`${IDLE_MIN} 分钟没操作 / 到点 / 落后 / 标星`,bad.length?'warn':'')}${kpi('到点未回访',due,'位客户',due?'warn':'')}${kpi('待我处理',todo,'求助与充值核实',todo?'warn':'')}</div><button class="primary small" data-page="assign">分配回访</button></div>
<div class="watch-grid"><section class="panel watch-board"><div class="panel-head"><div class="row"><h2>员工状态</h2><div class="seg" role="group" aria-label="筛选员工"><button data-watch-filter="all" class="${watchFilter==='all'?'active':''}">全部 ${rows.length}</button><button data-watch-filter="warn" class="${watchFilter==='warn'?'active':''}">需关注 ${bad.length}</button></div></div><span class="proto-note">需关注的排在前面 · 点一行看详情，↑↓ 切换</span></div><div class="watch-scroll"><table class="watch-table"><thead><tr>${watchTh()}</tr></thead><tbody>${list.map(r=>`<tr data-watch="${esc(r.n)}" tabindex="0" class="${r.n===watchSel?'selected':''}" aria-selected="${r.n===watchSel}"><td><span class="dot ${r.flags.length?'warn':'ok'}"></span><strong>${esc(r.n)}</strong>${r.help?'<span class="help-tag">求助</span>':''}</td><td><div class="wprog"><span class="progress"><i style="width:${r.r*100}%"></i></span><span class="num">${r.d}/${r.t}</span></div></td><td class="nowrap-cell ${r.idle>=IDLE_MIN?'warn-text':''}">${r.last?`<span class="num">${since(r.idle)}</span> · ${esc(r.last.text)}`:'<span class="muted">今天还没操作</span>'}</td><td class="nowrap-cell">${starBtn(r)}${r.flags.map(f=>`<span class="flag">${f}</span>`).join('')||`<span class="muted">${r.star?'已标记关注':'正常'}</span>`}${r.nudged?`<span class="nudged">${hm(r.nudged.t)} 已提醒</span>`:''}</td><td>${r.warn?`<button class="small nudge" data-nudge="${esc(r.n)}">${r.nudged?'再提醒':'提醒'}</button>`:''}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">所有人都在正常推进</td></tr>'}</tbody></table></div></section><aside class="watch-rail">${sel?watchDetail(sel):watchRail(ev)}</aside></div></div>`}
function rerenderWatch(focus,resetDetail=false){const qs=['.watch-scroll','.watch-feed','.rail-detail .panel-body'],keep=qs.map(q=>document.querySelector(q)?.scrollTop||0);render();qs.forEach((q,i)=>{const el=document.querySelector(q);if(el)el.scrollTop=resetDetail&&i===2?0:keep[i]});if(focus){const tr=document.querySelector(`[data-watch="${CSS.escape(focus)}"]`);if(tr){tr.focus({preventScroll:true});tr.scrollIntoView({block:'nearest'})}}}
