function healthPanel(){const h=kbHealth();return panel('知识库健康 · 近 7 天',`<div class="health-tiles">${h.tiles.map(([t,v,n,hint])=>`<div class="health-tile"><span>${t}</span><strong>${v}</strong><small>${n}</small><em>${hint}</em></div>`).join('')}</div>${h.gaps.length||h.recheck?`<div class="health-gaps">${h.gaps.map(g=>`<div class="settings-row"><div><strong>${g.s}</strong><p class="sub">本周被问 ${g.q} 次，已审核案例 ${g.c} 个</p></div><span class="badge orange">缺案例</span></div>`).join('')}${h.recheck?`<div class="settings-row"><div><strong>${h.recheck} 个案例可能与新口径冲突</strong><p class="sub">新结论生效后自动标出，请逐个复查</p></div><button class="small" data-kb="待复查">去复查</button></div>`:''}</div>`:''}<p class="footnote">数据少于 3 条时不显示百分比。“缺案例”按求助和沟通助手里的客户问题归类，演示版用关键词归类。</p>`)}
